顺序栈的 `top` 指向栈顶的**下一个空位**，容量为 4。连续压入 1~5（返回值未检查），再全部弹出并打印。输出是？

（下面省略 `#include` 与 `using namespace std;`）

```cpp
template <typename T>
class Stack {
    T* d; int top, cap;
public:
    explicit Stack(int c) : d(new T[c]), top(0), cap(c) {}
    ~Stack() { delete[] d; }
    bool push(const T& e) { if (top >= cap) return false; d[top++] = e; return true; }
    bool pop(T& e) { if (top == 0) return false; e = d[--top]; return true; }
    int size() const { return top; }
};

int main() {
    Stack<int> s(4);
    for (int i = 1; i <= 5; i++) s.push(i);      // 返回值没检查
    int v;
    while (s.pop(v)) cout << v;
    cout << " " << s.size() << "\n";
}
```

对 `{1, 2, 3, 5, 4}` 做带 `swapped` 标志的冒泡排序（一趟无交换就提前结束），下面程序输出「实际趟数 比较次数」，结果是？

（下面省略 `#include` 与 `using namespace std;`）

```cpp
int main() {
    int a[] = {1, 2, 3, 5, 4}, n = 5, pass = 0, cmp = 0;
    for (int i = 0; i < n - 1; i++) {
        bool swapped = false;
        for (int j = 0; j < n - 1 - i; j++) {
            cmp++;
            if (a[j] > a[j + 1]) { int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; swapped = true; }
        }
        pass++;
        if (!swapped) break;
    }
    cout << pass << " " << cmp << "\n";
}
```

